{
  "description": "The creature is a quadrupedal chimera shown in right-facing profile against a plain light background, standing on small pebbles and shell fragments. It has the head, thick neck ruff, underbelly fur and bushy tail of a gray wolf, but its back, sides, belly and all four legs are covered in a glossy, dark slate-blue segmented exoskeleton of overlapping plates, and its two front feet are enlarged into heavy crab-like pincers while its hind feet remain furry paws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a wolf's head with gray, white and beige fur, a long pointed muzzle, black nose, yellow-brown eyes, and fine whiskers, located at the front right end of the body"
    ,
      "where": "front right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed wolf ears with gray outer fur and lighter inner fur",
      "where": "on top of the head"
    },
    {
      "part": "mane / neck fur",
      "looks_like": "thick, shaggy, long gray and white fur forming a ruff around the neck and chest and continuing as lighter beige-gray fur along the exposed underbelly between the plated areas",
      "where": "around neck, chest and underside"
    },
    {
      "part": "torso",
      "looks_like": "elongated wolf-like torso whose dorsal and lateral surfaces are covered by overlapping glossy dark bluish-gray plates",
      "where": "middle of body between neck and tail"
    },
    {
      "part": "plates",
      "looks_like": "glossy, hard, overlapping segmented armor plates in dark slate-blue with visible ridges and segment lines, covering the back from the base of the neck to the base of the tail, the sides, a band across the lower belly, and encasing all four legs",
      "where": "covering back, sides, belly and legs"
    },
    {
      "part": "legs",
      "looks_like": "four thick jointed legs, the two front legs more robust and heavily plated, the two hind legs slightly more slender and also plated with visible joints at knee and ankle",
      "where": "two front under the chest, two hind under the hips"
    },
    {
      "part": "feet",
      "looks_like": "front feet are large dark bluish-gray crab-like chelae with two curved pincers each and a fringe of pale fur at the wrist; hind feet are pale furry wolf paws with dark claws and small dark nails",
      "where": "at the ends of the legs, front pair are pincers, hind pair are paws on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, bushy wolf tail with dense gray and white hair, the dorsal base overlapped by small pointed plates",
      "where": "at the rear left end of the body"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "crab",
    "isopod"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
